custom_qss:
/* ============================================================
   SIENNA — copper & rose on dark espresso.
   Warm, not muddy. Gradient-forward, but NOT the old clashing-
   diagonal mess: gradients are asymmetric vertical falls that
   read as metal catching light, plus a copper->rose sweep on
   interactive fills. Typography: Georgia serif for headers,
   Cascadia Code mono for numeric values, Segoe UI body.
   ============================================================ */

/* ---------- base type ---------- */
* {
    font-family: Segoe UI, Calibri, Ubuntu, sans-serif;
    color: #f0e0d4;
}
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent;
    border: none;
}

/* ---------- window: asymmetric vertical metal fall ---------- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #241610, stop:0.4 #22150f, stop:0.75 #1a100c, stop:1 #140c08) !important;
    border-top: 1px solid #553726;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #241610, stop:1 #1a100c) !important;
    border: 1px solid #3a2519;
    border-top: 1px solid #e08b4c;
}

/* ---------- menubar: flat strip, copper active ---------- */
QMenuBar {
    background: #191009 !important;
    border-bottom: 1px solid #3a2519;
    padding: 2px 0;
}
QMenuBar::item {
    background: transparent;
    color: #c4a890;
    padding: 5px 12px;
    font-size: 12px;
    letter-spacing: 0.3px;
}
QMenuBar::item:selected {
    background: #2e1d15;
    color: #f5b87a;
}

/* ---------- popup menus ---------- */
QMenu {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1a12, stop:1 #1a100c) !important;
    border: 1px solid #553726;
    padding: 4px;
    font-size: 12px;
}
QMenu::item {
    padding: 6px 28px 6px 16px;
    border-radius: 3px;
    color: #f0e0d4;
    background: transparent;
}
QMenu::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e08b4c, stop:1 #7a3028) !important;
    color: #ffffff;
}
QMenu::item:disabled {
    color: #5a4030;
}
QMenu::separator {
    height: 1px;
    background: #3a2519;
    margin: 5px 10px;
}

/* ---------- toolbar: flat, copper active ---------- */
QToolBar {
    background: #191009 !important;
    border-bottom: 1px solid #3a2519;
    spacing: 4px;
    padding: 4px;
}
QToolBar::separator {
    background: #3a2519;
    width: 1px;
    margin: 6px 4px;
}
QToolBar::handle {
    background: #553726;
    width: 8px;
}
QToolBar QToolButton {
    background: transparent;
    border: 1px solid transparent;
    border-radius: 4px;
    padding: 5px 9px;
    color: #c4a890;
    font-size: 12px;
}
QToolBar QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2e1d15, stop:1 #22150f) !important;
    border: 1px solid #553726;
    color: #f5b87a;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e08b4c, stop:1 #7a4520) !important;
    border: 1px solid #e08b4c;
    color: #ffffff;
}

/* ---------- buttons: metal gradient, copper->rose sweep on hover ---------- */
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1a12, stop:0.5 #22150f, stop:1 #1a100c) !important;
    border: 1px solid #3a2519;
    border-radius: 4px;
    padding: 6px 18px;
    color: #f0e0d4;
    font-size: 12px;
    font-weight: 500;
}
QPushButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #e08b4c, stop:0.5 #f5b87a, stop:1 #e0655a) !important;
    border: 1px solid #f5b87a;
    color: #1a100c;
}
QPushButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #7a4520, stop:1 #7a3028) !important;
    color: #f5b87a;
}
QPushButton:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #7a4520, stop:1 #22150f) !important;
    border: 1px solid #e08b4c;
    color: #f5b87a;
}
QPushButton:default {
    border: 1px solid #e08b4c;
}
QPushButton:disabled {
    color: #5a4030;
    border: 1px solid #3a2519;
}
QPushButton:focus {
    outline: none;
}

/* ---------- inputs: recessed, mono, copper focus ---------- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #120a07 !important;
    border: 1px solid #3a2519;
    border-radius: 4px;
    padding: 5px 8px;
    color: #f0e0d4;
    font-family: Cascadia Code, Consolas, monospace;
    font-size: 12px;
    selection-background-color: #7a4520;
    selection-color: #f0e0d4;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus,
QTextEdit:focus, QPlainTextEdit:focus {
    border: 1px solid #e08b4c;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #5a4030;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent;
    border: none;
    width: 14px;
}

QComboBox {
    background: #120a07 !important;
    border: 1px solid #3a2519;
    border-radius: 4px;
    padding: 5px 8px;
    color: #f0e0d4;
    font-size: 12px;
}
QComboBox:hover {
    border: 1px solid #553726;
}
QComboBox:focus {
    border: 1px solid #e08b4c;
}
QComboBox::drop-down {
    border: none;
    background: transparent;
    width: 16px;
}
QComboBox QAbstractItemView {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1a12, stop:1 #1a100c) !important;
    border: 1px solid #553726;
    selection-background-color: #2e1d15;
    selection-color: #f5b87a;
    outline: none;
}
QComboBox:disabled {
    color: #5a4030;
}

/* ---------- checkboxes: copper check ---------- */
QCheckBox, QRadioButton {
    background: transparent;
    color: #f0e0d4;
    spacing: 7px;
    font-size: 12px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 14px;
    height: 14px;
    background: #120a07;
    border: 1px solid #553726;
    border-radius: 3px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    border: 1px solid #e08b4c;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #e08b4c, stop:1 #7a4520) !important;
    border: 1px solid #e08b4c;
}

/* ---------- tabs: copper underline, serif selected label ---------- */
QTabBar::tab {
    background: transparent;
    color: #8a6a55;
    padding: 8px 16px;
    border: none;
    border-bottom: 2px solid transparent;
    font-size: 12px;
    letter-spacing: 0.4px;
}
QTabBar::tab:hover {
    color: #f0e0d4;
}
QTabBar::tab:selected {
    color: #f5b87a;
    border-bottom: 2px solid #e08b4c;
    font-family: Georgia, Georgia, serif;
    font-weight: 700;
}
QTabWidget::pane {
    border: none;
    border-top: 1px solid #3a2519;
    background: #1a100c;
}

/* ---------- docks: metal gradient, copper title rule ---------- */
QDockWidget {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #241610, stop:0.6 #22150f, stop:1 #1a100c) !important;
    border: 1px solid #3a2519;
}
QDockWidget::title {
    background: #191009 !important;
    border-bottom: 1px solid #3a2519;
    border-left: 2px solid #7a4520;
    padding: 6px 10px;
    color: #c4a890;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1.2px;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent;
    border: none;
    border-radius: 3px;
    padding: 2px;
    icon-size: 12px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: #2e1d15;
}

/* ---------- group boxes: serif copper label, left tick ---------- */
QGroupBox {
    background: transparent;
    border: 1px solid #3a2519;
    border-left: 2px solid #7a4520;
    border-radius: 4px;
    margin-top: 12px;
    padding-top: 10px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1px;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 8px;
    color: #e08b4c;
    font-family: Georgia, Georgia, serif;
    font-weight: 700;
    background: #1a100c;
}

/* ---------- item views ---------- */
QAbstractItemView {
    background: #120a07 !important;
    border: 1px solid #3a2519;
    border-radius: 4px;
    alternate-background-color: #191009;
    outline: none;
    selection-background-color: #2e1d15;
    selection-color: #f5b87a;
    font-size: 12px;
}
QAbstractItemView::item {
    padding: 5px 8px;
    border: none;
    color: #f0e0d4;
}
QAbstractItemView::item:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #2e1d15, stop:1 #22150f) !important;
}
QAbstractItemView::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #2e1d15, stop:1 #120a07) !important;
    color: #f5b87a;
    border-left: 2px solid #e08b4c;
}
QAbstractItemView::item:selected:!active {
    background: #191009;
    color: #c4a890;
}
QTreeView::branch {
    background: transparent;
}
QHeaderView::section {
    background: #191009 !important;
    border: none;
    border-bottom: 1px solid #553726;
    border-right: 1px solid #3a2519;
    padding: 6px 10px;
    color: #8a6a55;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.8px;
}

/* ---------- scrollbars: thin, copper handle ---------- */
QScrollBar:vertical {
    background: #120a07;
    width: 10px;
    margin: 0;
    border: none;
}
QScrollBar::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #553726, stop:1 #3a2519) !important;
    border-radius: 5px;
    min-height: 30px;
}
QScrollBar::handle:vertical:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #e08b4c, stop:1 #7a4520) !important;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    border: none;
    background: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: none;
}
QScrollBar:horizontal {
    background: #120a07;
    height: 10px;
    margin: 0;
    border: none;
}
QScrollBar::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #553726, stop:1 #3a2519) !important;
    border-radius: 5px;
    min-width: 30px;
}
QScrollBar::handle:horizontal:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e08b4c, stop:1 #7a4520) !important;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    border: none;
    background: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: none;
}
QScrollBar::corner {
    background: none;
}

/* ---------- sliders: copper->rose fill, ice-copper handle ---------- */
QSlider::groove:horizontal {
    background: #120a07;
    border: 1px solid #3a2519;
    height: 4px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e08b4c, stop:1 #e0655a) !important;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background: #120a07;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #f5b87a, stop:1 #e08b4c) !important;
    width: 12px;
    height: 12px;
    margin: -5px 0;
    border: 1px solid #e08b4c;
    border-radius: 7px;
}
QSlider::handle:horizontal:hover {
    background: #f59489;
    border: 1px solid #e0655a;
}
QSlider::groove:vertical {
    background: #120a07;
    border: 1px solid #3a2519;
    width: 4px;
    border-radius: 2px;
}
QSlider::sub-page:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #e08b4c, stop:1 #e0655a) !important;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #f5b87a, stop:1 #e08b4c) !important;
    width: 12px;
    height: 12px;
    margin: 0 -5px;
    border: 1px solid #e08b4c;
    border-radius: 7px;
}

/* ---------- progress: copper->rose sweep ---------- */
QProgressBar {
    background: #120a07;
    border: 1px solid #3a2519;
    border-radius: 3px;
    text-align: center;
    color: #c4a890;
    font-size: 11px;
    min-height: 14px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e08b4c, stop:1 #e0655a) !important;
    border-radius: 2px;
}

/* ---------- statusbar: flat ---------- */
QStatusBar {
    background: #191009 !important;
    border-top: 1px solid #3a2519;
    color: #8a6a55;
    font-size: 11px;
}
QStatusBar::item {
    border: none;
}
QStatusBar QLabel {
    color: #8a6a55;
    font-size: 11px;
}

/* ---------- tooltip ---------- */
QToolTip {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1a12, stop:1 #1a100c) !important;
    border: 1px solid #553726;
    border-radius: 4px;
    padding: 6px 10px;
    color: #f0e0d4;
    font-size: 12px;
}

/* ---------- splitters ---------- */
QSplitter::handle {
    background: #3a2519;
}
QSplitter::handle:hover {
    background: #7a4520;
}

/* ---------- secondary list widgets ---------- */
QListView, QListWidget, QTreeWidget, QTableWidget {
    background: #120a07 !important;
    border: 1px solid #3a2519;
    border-radius: 4px;
    outline: none;
}
QTableCornerButton::section {
    background: #191009;
    border: 1px solid #3a2519;
}
